/** AppShell: desktop panes retain their geometry; below lg, content opens details as a separate view. */
import type { ReactNode } from "react"
import { useBreakpointTier } from "./useBreakpointTier"
import { detailedLayoutPanes } from "./layoutPanes"
import { breakpoints } from "../theme/breakpoints.config"
import { Sidebar } from "./Sidebar"
import { BottomNav } from "./BottomNav"
import { ResponsivePanes, type PaneNavigationProps } from "./ResponsivePanes"
import type { NavItem } from "./navItems"
import "./layout.css"

export function AppShell({
  sidebar, navigation = [], content, inspector, ...paneNavigation
}: PaneNavigationProps & {
  sidebar: ReactNode
  navigation?: NavItem[]
  content: ReactNode
  inspector: ReactNode
}) {
  const tier = useBreakpointTier()
  const sidebarWidth = breakpoints.find((b) => b.name === tier)!.sidebarWidth
  const pane = detailedLayoutPanes[tier]

  return (
    <div className="neon-layout bg-background font-sans text-body text-foreground" data-bottom-nav={navigation.length > 0}>
      <Sidebar workspace width={sidebarWidth} navigation={navigation}>{sidebar}</Sidebar>
      <ResponsivePanes
        {...paneNavigation} content={content} inspector={inspector}
        compact={tier === "sm" || tier === "md"}
        contentWidth={pane.content === "hidden" ? undefined : pane.content}
        capAt={pane.inspector.capAt}
      />
      <BottomNav workspace navigation={navigation} />
    </div>
  )
}

/** Mobile navigation reserves matching space through layout.css, including the device safe area. */
import "./layout.css"
import { useBreakpointTier } from "./useBreakpointTier"
import type { NavItem } from "./navItems"

// Icons take primary-foreground, the role for content on the primary fill, in both modes.
export function BottomNav({ navigation = [], workspace = false }: { navigation?: NavItem[]; workspace?: boolean }) {
  const tier = useBreakpointTier()
  if (tier !== "sm" || navigation.length === 0) return null

  return (
    <nav
      className={`neon-bottom-nav fixed inset-x-0 bottom-0 z-10 flex items-center justify-around border-t ${workspace ? "bg-background text-foreground" : "bg-primary text-primary-foreground"}`}
      aria-label="Primary navigation"
    >
      {navigation.map(({ icon: Icon, ...item }) => (
        <a
          key={item.href}
          href={item.href}
          target={item.external ? "_blank" : undefined}
          rel={item.external ? "noopener noreferrer" : undefined}
          aria-label={item.label}
          aria-current={item.active ? "page" : undefined}
          className="flex items-center justify-center text-inherit no-underline"
        >
          <Icon className="size-6" />
        </a>
      ))}
    </nav>
  )
}

/** ContentLayout: desktop panes retain their geometry; below lg, content opens details as a separate view. */
import type { ReactNode } from "react"
import { useBreakpointTier } from "./useBreakpointTier"
import { contentLayoutPanes } from "./layoutPanes"
import { breakpoints } from "../theme/breakpoints.config"
import { Sidebar } from "./Sidebar"
import { BottomNav } from "./BottomNav"
import { ResponsivePanes, type PaneNavigationProps } from "./ResponsivePanes"
