  sidebar, navigation = [], content, inspector, ...paneNavigation
}: PaneNavigationProps & {
  sidebar: ReactNode
  navigation?: NavItem[]
  content: ReactNode
  inspector: ReactNode
}) {
  const tier = useBreakpointTier()
  const sidebarWidth = breakpoints.find((b) => b.name === tier)!.sidebarWidth
  const pane = contentLayoutPanes[tier]

