import type { ReactNode } from "react";

/** Fixed-width or full-width pane with a toolbar and independently scrollable body. */
export function ContentView({ width, children, toolbar, capAt, divider = false }: {
  width: number | string; children: ReactNode; toolbar?: ReactNode; capAt?: number; divider?: boolean;
}) {
  return (
    <div className={divider ? "border-e border-border" : undefined} style={{ boxSizing: "border-box", width, maxWidth: capAt, marginInline: capAt ? "auto" : undefined, flexShrink: 0, display: "flex", flexDirection: "column", height: "100%", minHeight: 0 }}>
      <div className="border-b border-border" data-pane-control style={{ boxSizing: "border-box", minHeight: 64, flexShrink: 0, display: "flex", alignItems: "center", paddingInline: 16 }}>
        {toolbar}
      </div>
      <div style={{ flex: 1, minHeight: 0, overflowY: "auto" }}>{children}</div>
    </div>
  );
}

import type { ReactNode } from "react";
import type { InspectorPane } from "./layoutPanes";

/** Fill pane with an optional content cap, toolbar and independently scrollable body. */
export function InspectorView({ pane, children, toolbar, headerDivider = true }: {
  pane: InspectorPane; children: ReactNode; toolbar?: ReactNode; headerDivider?: boolean;
}) {
  return (
    <div style={{ flex: 1, minWidth: 0, minHeight: 0, height: "100%" }}>
      <div style={{ maxWidth: pane.capAt, marginInline: pane.capAt ? "auto" : undefined,
        height: "100%", display: "flex", flexDirection: "column" }}>
        <div className={headerDivider ? "border-b border-border" : undefined} data-pane-control style={{ boxSizing: "border-box", minHeight: 64, flexShrink: 0, display: "flex", alignItems: "center", paddingInline: 16 }}>
          {toolbar}
        </div>
        <div style={{ flex: 1, minHeight: 0, overflowY: "auto" }}>{children}</div>
      </div>
    </div>
  );
}

import { useLayoutEffect, useRef, useState, type ReactNode } from "react"
import { ArrowLeft } from "lucide-react"
import { Button } from "@/components/ui/button"
import { ContentView } from "./ContentView"
import { InspectorView } from "./InspectorView"

export type ActivePane = "content" | "inspector"

export interface PaneNavigationProps {
  /** Context and app-owned actions in each pane's persistent 64px header. */
  contentHeader?: ReactNode
  contentActions?: ReactNode
  inspectorHeader?: ReactNode
  inspectorActions?: ReactNode
  /** Omit for internal pane state. Controlled callers must update this in onActivePaneChange. */
  activePane?: ActivePane
  onActivePaneChange?: (pane: ActivePane) => void
  paneLabels?: {
    content?: string
    inspector?: string
    viewDetails?: string
    backToContent?: string
  }
}

/** Keep pane subtrees mounted across selection and breakpoint changes. */
export function ResponsivePanes({
  content, inspector, compact, contentWidth, inspectorWidth, capAt, contentCapAt,
  activePane, onActivePaneChange, paneLabels,
  contentHeader, contentActions, inspectorHeader, inspectorActions,
}: PaneNavigationProps & {
  content: ReactNode
  inspector: ReactNode
  compact: boolean
  contentWidth?: number
  inspectorWidth?: number
  capAt?: number
  contentCapAt?: number
}) {
  const [internalPane, setInternalPane] = useState<ActivePane>("content")
  const current = activePane ?? internalPane
  const contentRef = useRef<HTMLElement>(null)
  const inspectorRef = useRef<HTMLElement>(null)
  const returnFocus = useRef<HTMLElement | null>(null)
  const previous = useRef({ compact, current })
  const labels = {
    content: "Content", inspector: "Details",
    viewDetails: "View details", backToContent: "Back to content",
    ...paneLabels,
  }

  function changePane(next: ActivePane) {
    if (activePane === undefined) setInternalPane(next)
    onActivePaneChange?.(next)
  }

  useLayoutEffect(() => {
    const before = previous.current
    const active = document.activeElement
    const hiddenHasFocus = current === "content"
      ? inspectorRef.current?.contains(active)
      : contentRef.current?.contains(active)
    if (compact && (before.current !== current || (!before.compact && hiddenHasFocus))) {
      if (current === "inspector") {
        inspectorRef.current?.focus({ preventScroll: true })
      } else {
        const target = returnFocus.current
        if (target?.isConnected && contentRef.current?.contains(target)) {
          target.focus({ preventScroll: true })
        } else {
          contentRef.current?.focus({ preventScroll: true })
        }
      }
    } else if (!compact && before.compact &&
      (active === document.body || active instanceof HTMLElement && active.closest('[data-pane-control]'))) {
      // The mobile toolbar disappears on desktop; leave focus in the same pane.
      (current === "content" ? contentRef : inspectorRef).current?.focus({ preventScroll: true })
    }
    previous.current = { compact, current }
  }, [compact, current])

  const contentToolbar = compact ? (
    <Button type="button" variant="secondary" size="sm" onClick={() => changePane("inspector")}>
      {labels.viewDetails}
    </Button>
  ) : undefined
  const inspectorToolbar = compact ? (
    <Button type="button" variant="ghost" size="sm" className="-ms-3" onClick={() => changePane("content")}>
      <ArrowLeft />
      {labels.backToContent}
    </Button>
  ) : undefined

  return (
    <>
      <section className={!compact && inspectorWidth === undefined ? "border-e border-border" : undefined}
        ref={contentRef} tabIndex={-1} aria-label={labels.content}
        hidden={compact && current !== "content"}
        onFocusCapture={(event) => {
          if (event.target !== contentRef.current) returnFocus.current = event.target as HTMLElement
        }}
        style={{ boxSizing: "border-box", display: compact && current !== "content" ? "none" : "flex",
          flex: compact || contentWidth === undefined ? 1 : undefined,
          width: compact ? undefined : contentWidth, flexShrink: 0, minWidth: 0, minHeight: 0, height: "100%",
          order: inspectorWidth === undefined ? 0 : 1 }}
      >
        <ContentView width="100%" capAt={compact ? undefined : contentCapAt} toolbar={<div className="neon-pane-header">
          <div className="neon-pane-heading">{contentHeader}</div>
          <div className="neon-pane-actions">{contentActions}{contentToolbar}</div>
        </div>}>
          {content}
        </ContentView>
      </section>
      <section className={!compact && inspectorWidth !== undefined ? "border-e border-border" : undefined}
        ref={inspectorRef} tabIndex={-1} aria-label={labels.inspector}
        hidden={compact && current !== "inspector"}
        style={{ boxSizing: "border-box", display: compact && current !== "inspector" ? "none" : "flex",
          flex: compact || inspectorWidth === undefined ? 1 : undefined,
          width: compact ? undefined : inspectorWidth, flexShrink: 0, minWidth: 0, minHeight: 0, height: "100%" }}
      >
        <InspectorView pane={{ capAt: compact ? undefined : capAt }} toolbar={<div className="neon-pane-header">
          {inspectorToolbar}
          <div className="neon-pane-heading">{inspectorHeader}</div>
          <div className="neon-pane-actions">{inspectorActions}</div>
        </div>}>
          {inspector}
        </InspectorView>
      </section>
    </>
  )
}

/**
 * Renders the caller-supplied nav list (see ./navItems.ts's `NavItem`)
 * inside the Sidebar's scrollable content slot. `isRail` switches between
 * icon-only (64px tier) and icon+label (full-width tiers) — see
 * ./Sidebar.tsx. `items` is empty by default; nothing renders until a
 * layout is given a `navigation` array.
 */
import { cn } from "@/lib/utils"
import type { NavItem } from "./navItems"

export function SidebarNav({ items, isRail }: { items: NavItem[]; isRail: boolean }) {
  if (items.length === 0) return null

  return (
    <nav className="flex flex-col gap-1 p-2">
      {items.map(({ icon: Icon, ...item }) => (
        <a
          key={item.href}
          href={item.href}
          target={item.external ? "_blank" : undefined}
          rel={item.external ? "noopener noreferrer" : undefined}
          aria-label={item.label}
          aria-current={item.active ? "page" : undefined}
          className={cn("flex items-center gap-2 rounded-md p-2 text-foreground no-underline", isRail ? "justify-center" : "justify-start")}
        >
          <Icon className="size-6" />
          {!isRail && <span className="neon-sidebar-label">{item.label}</span>}
        </a>
      ))}
    </nav>
  )
}

.neon-layout {
  --neon-safe-area-bottom: env(safe-area-inset-bottom, 0px);
  display: flex;
  width: 100%;
  height: 100vh;
  height: 100dvh;
  box-sizing: border-box;
  overflow: hidden;
}

@media (max-width: 499px) {
  .neon-layout[data-bottom-nav="true"] {
    padding-bottom: calc(56px + var(--neon-safe-area-bottom));
  }
}

.neon-bottom-nav {
  height: calc(56px + var(--neon-safe-area-bottom));
  padding-bottom: var(--neon-safe-area-bottom);
  box-sizing: border-box;
}

.neon-bottom-nav a {
  min-width: 44px;
  min-height: 44px;
}

.neon-bottom-nav a:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: -2px;
}

/* Workspace geometry is maintained separately from the raw breakpoint export.
   Order history: hidden below 500, 64px rail below 1280, then 240px sidebar. */
.neon-workspace-sidebar {
  width: 64px;
}

.neon-workspace-sidebar > :first-child {
  padding-inline: 8px;
  justify-content: center;
}

.neon-sidebar-wordmark,
.neon-workspace-sidebar .neon-sidebar-label {
  display: none;
}

.neon-sidebar-body {
  display: flex;
  flex-direction: column;
  justify-content: safe center;
}

.neon-workspace-sidebar nav a {
  min-height: 48px;
  box-sizing: border-box;
  justify-content: center;
}

/* Custom sidebar content remains reachable in rail mode as well. */
.neon-workspace-sidebar .neon-sidebar-content {
  overflow-wrap: anywhere;
}

.neon-pane-header {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-width: 0;
  padding-block: 8px;
}

.neon-pane-heading {
  flex: 1;
  min-width: 0;
  overflow-wrap: anywhere;
}

.neon-pane-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}

@media (min-width: 1280px) {
  .neon-workspace-sidebar { width: 240px; }
  .neon-workspace-sidebar > :first-child { justify-content: flex-start; padding-inline: 16px; }
  .neon-sidebar-symbol { display: none; }
  .neon-sidebar-wordmark,
  .neon-workspace-sidebar .neon-sidebar-label { display: block; }
  .neon-workspace-sidebar nav a { justify-content: flex-start; }
}

/**
 * Framework-agnostic breakpoint hook, keyed off ../theme/breakpoints.config.ts
 * (copied in from neon-create at scaffold time).
 *
 * Confirmed (against the real @coinbase/cds-web@9.26.1 types) that
 * MediaQueryProvider does NOT accept a custom-breakpoints prop — its only
 * props are `children` and `defaultValues` (a one-time initial snapshot,
 * not a breakpoint config, per dts/system/MediaQueryProvider.d.ts). This
 * plain matchMedia-based hook is the correct approach here, not a
 * placeholder pending verification — see neon-create/SKILL.md's known
 * limitations for the citation.
 */
import { useEffect, useState } from "react";
import { breakpoints, type BreakpointName } from "../theme/breakpoints.config";

/**
 * Breakpoints are sorted narrowest-to-widest and contiguous, so scanning
 * from the widest down and returning the first tier whose minWidth is at
 * or below the given width correctly handles every width in range. Widths
 * narrower than the first tier's minWidth (< 320px) fall through to the
 * first (narrowest) tier, not the last — a fixed bug: the previous
 * forward-scanning version fell through to the *widest* tier for any
 * out-of-range width, so a sub-320px viewport got a full desktop layout.
 */
function tierForWidth(width: number): BreakpointName {
  for (let i = breakpoints.length - 1; i >= 0; i--) {
    if (width >= breakpoints[i].minWidth) return breakpoints[i].name;
  }
  return breakpoints[0].name;
}

export function useBreakpointTier(): BreakpointName {
  const [tier, setTier] = useState<BreakpointName>(() =>
    typeof window === "undefined" ? breakpoints[0].name : tierForWidth(window.innerWidth)
  );

  useEffect(() => {
    const update = () => setTier(tierForWidth(window.innerWidth));
    update();
    window.addEventListener("resize", update);
    return () => window.removeEventListener("resize", update);
  }, []);

  return tier;
}

/**
 * Finnomena responsive breakpoint/grid tiers — projected from
 * tokens/breakpoint.json's "Detailed Layout" variant.
 *
 * GENERATED FILE — do not hand-edit. Regenerate with:
 *   node theme/scripts/sync-tokens.mjs && node theme/scripts/generate-breakpoints-config.mjs
 *
 * This file covers viewport ranges, sidebar rail/full width, and grid
 * rhythm (gutter/end-margins/columns) only. It does NOT cover Content/
 * Inspector pane widths for the 3-pane app shell — those come from a
 * separate Figma frame read, not this token export (see
 * templates/vitejs-cds/src/layout/layoutPanes.ts for that data
 * and why it's kept separate).
 */
export interface BreakpointTier {
  name: "sm" | "md" | "lg" | "xl" | "xxl" | "xxxl" | "max";
  minWidth: number;
  maxWidth: number;
  /** Sidebar width at this tier: 0 = hidden, 64 = icon-rail, >64 = full sidebar. */
  sidebarWidth: number;
  gutter: number;
  endMargins: number;
  columns: number;
}

export const breakpoints: readonly BreakpointTier[] = [
  { name: "sm", minWidth: 320, maxWidth: 499, sidebarWidth: 0, gutter: 16, endMargins: 16, columns: 4 },
  { name: "md", minWidth: 500, maxWidth: 987, sidebarWidth: 64, gutter: 16, endMargins: 16, columns: 8 },
  { name: "lg", minWidth: 988, maxWidth: 1079, sidebarWidth: 64, gutter: 16, endMargins: 16, columns: 12 },
  { name: "xl", minWidth: 1080, maxWidth: 1271, sidebarWidth: 240, gutter: 16, endMargins: 16, columns: 12 },
  { name: "xxl", minWidth: 1272, maxWidth: 1439, sidebarWidth: 320, gutter: 16, endMargins: 16, columns: 12 },
  { name: "xxxl", minWidth: 1440, maxWidth: 1919, sidebarWidth: 360, gutter: 24, endMargins: 24, columns: 12 },
  { name: "max", minWidth: 1920, maxWidth: 3840, sidebarWidth: 360, gutter: 24, endMargins: 24, columns: 12 },
] as const;

export type BreakpointName = BreakpointTier["name"];
